import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/pet.dart';import 'pet_editor_screen.dart';import 'pet_profile_screen.dart';import '../../../shared/widgets/empty_state.dart';
class PetsScreen extends ConsumerWidget{const PetsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);final pets=c.pets;return Scaffold(appBar:AppBar(title:const Text('My Pets'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const PetEditorScreen())),icon:const Icon(Icons.add))]),body:pets.isEmpty?Center(child:Padding(padding:const EdgeInsets.all(20),child:EmptyState(title:'No pets yet',message:'Create a private profile for your dog or cat.',action:'Add pet',onAction:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const PetEditorScreen())))):ListView(padding:const EdgeInsets.all(16),children:[...pets.map((p)=>_PetTile(pet:p,selected:p.id==c.selectedPetId,onTap:(){if(!p.archived)c.selectPet(p.id);Navigator.push(context,MaterialPageRoute(builder:(_)=>PetProfileScreen(pet:p)));},onEdit:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PetEditorScreen(pet:p))),onArchive:()=>c.save('pets',p.copyWith(archived:!p.archived).toMap()))) ]));}}
class _PetTile extends StatelessWidget{const _PetTile({required this.pet,required this.selected,required this.onTap,required this.onEdit,required this.onArchive});final Pet pet;final bool selected;final VoidCallback onTap,onEdit,onArchive;@override Widget build(BuildContext context)=>Card(child:ListTile(onTap:onTap,leading:CircleAvatar(backgroundColor:const Color(0xFFEAF2E8),child:Icon(pet.species=='Cat'?Icons.cruelty_free:Icons.pets,color:const Color(0xFF39845A))),title:Text(pet.name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${pet.species} · ${pet.breed.isEmpty?'Mixed / unknown':pet.breed}${pet.archived?' · Archived':''}'),trailing:PopupMenuButton<String>(onSelected:(v)=>v=='edit'?onEdit():onArchive(),itemBuilder:(_)=>[const PopupMenuItem(value:'edit',child:Text('Edit')),PopupMenuItem(value:'archive',child:Text(pet.archived?'Restore':'Archive'))]),selected:selected));}}
